\choiceTF
{ \True  Đường cao của tam giác là ${\dfrac{19 \sqrt{3}}{2}}$ cm }
   {  Bán kính đường tròn ngoại tiếp tam giác bằng ${\dfrac{38 \sqrt{3}}{3}}$ cm }
     {  Bán kính đường tròn nội tiếp tam giác bằng ${\dfrac{19 \sqrt{3}}{9}}$ cm }
    { \True Diện tích tam giác bằng ${\dfrac{361 \sqrt{3}}{4}}$ cm }
\loigiai{
a) \textbf{Đúng}. Đường cao tam giác đều cạnh $a = 19$ là $h = \dfrac{a\sqrt{3}}{2} = \dfrac{19 \sqrt{3}}{2}$ cm.\\
b) \textbf{Sai}. Bán kính đường tròn ngoại tiếp là $R = \dfrac{a\sqrt{3}}{3} = \dfrac{19 \sqrt{3}}{3}$ cm.\\
c) \textbf{Sai}. Bán kính đường tròn nội tiếp là $r = \dfrac{a\sqrt{3}}{6} = \dfrac{19 \sqrt{3}}{6}$ cm.\\
d) \textbf{Đúng}. Diện tích tam giác đều là $S = \dfrac{a^2\sqrt{3}}{4} = \dfrac{361 \sqrt{3}}{4}$ $\text{cm}^2$.
}\end{ex}

